import { describe, expect, it } from 'vitest'

/**
 * A screen's .ts holds data binding and nothing else: it reads the stores, builds `use(...)` trees
 * with the engine, and hands over tap handlers that call actions. So it may import only:
 * the stores, the actions, the UI state module (types and queries), the declarative engine, the
 * shared screen helpers, its own .kdl/.css sources, and pure core modules.
 * shared.ts is the one place game-wide registrations (and their pixi drawing) live, so it is exempt.
 */
const CORE = [
  'game', 'rewards', 'content', 'content-load', 'tuning', 'rng',
] // mirrors CORE in src/core-purity.test.ts

const RAW = import.meta.glob<string>(['./*.ts', '!./shared.ts', '!./*.test.ts'], { query: '?raw', import: 'default', eager: true })

const strip = (src: string) =>
  src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"`\\])\/\/.*$/gm, '$1')

const specifiers = (src: string) =>
  [...src.matchAll(/(?:\bfrom\s*|\bimport\s*\(?\s*)['"]([^'"]+)['"]/g)].map((m) => m[1]!)

const allowed = (name: string, s: string) =>
  ['../store', '../actions', '../decl/engine', './shared'].includes(s) ||
  s === `./${name}.kdl?raw` || s === `./${name}.css?raw` ||
  (s.startsWith('../') && CORE.includes(s.slice(3)))

describe('screen imports', () => {
  it('finds the screens', () => {
    expect(Object.keys(RAW)).toContain('./title.ts')
  })

  for (const [path, raw] of Object.entries(RAW)) {
    const name = path.slice(2, -3)
    it(`${name}.ts imports only stores, actions, the engine, shared helpers, its sources, or core`, () => {
      expect(specifiers(strip(raw)).filter((s) => !allowed(name, s)).map((s) => `${name}.ts imports '${s}'`)).toEqual([])
    })
  }
})
